namespace sv_6329355a38764fa5b99dca67fe45b0e3.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

@* Displays the step progress bar with clickable completed steps *@

<nav class="step-indicator" aria-label="Application progress">
    <ol class="step-list">
        @for (int i = 0; i < StepNames.Count; i++)
        {
            var stepIndex = i;
            var stepNumber = i + 1;
            var css = GetStepCss(stepIndex);
            <li class="step-item @css">
                @if (stepIndex < CurrentStep)
                {
                    <button class="step-button completed" @onclick="() => OnStepClicked.InvokeAsync(stepIndex)">
                        <span class="step-icon">&#10003;</span>
                        <span class="step-label">@StepNames[stepIndex]</span>
                    </button>
                }
                else
                {
                    <span class="step-button @css">
                        <span class="step-icon">@stepNumber</span>
                        <span class="step-label">@StepNames[stepIndex]</span>
                    </span>
                }
            </li>
        }
    </ol>
</nav>

<style>
    .step-indicator {
        margin-bottom: 2rem;
    }
    .step-list {
        display: flex;
        list-style: none;
        padding: 0;
        margin: 0;
        justify-content: space-between;
    }
    .step-item {
        flex: 1;
        text-align: center;
        position: relative;
    }
    .step-item:not(:last-child)::after {
        content: '';
        position: absolute;
        top: 1rem;
        left: 55%;
        width: 90%;
        height: 2px;
        background: #ddd;
    }
    .step-item.completed:not(:last-child)::after {
        background: #198754;
    }
    .step-button {
        display: inline-flex;
        flex-direction: column;
        align-items: center;
        gap: 0.25rem;
        border: none;
        background: none;
        cursor: default;
        padding: 0.25rem;
        font-size: 0.85rem;
    }
    button.step-button {
        cursor: pointer;
    }
    .step-icon {
        width: 2rem;
        height: 2rem;
        border-radius: 50%;
        display: flex;
        align-items: center;
        justify-content: center;
        font-weight: bold;
        background: #e9ecef;
        color: #6c757d;
    }
    .step-item.completed .step-icon {
        background: #198754;
        color: white;
    }
    .step-item.active .step-icon {
        background: #0d6efd;
        color: white;
    }
    .step-item.future .step-icon {
        background: #e9ecef;
        color: #adb5bd;
    }
    .step-label {
        color: #6c757d;
        white-space: nowrap;
    }
    .step-item.active .step-label {
        color: #0d6efd;
        font-weight: 600;
    }
    .step-item.completed .step-label {
        color: #198754;
    }
</style>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public EventCallback<int> OnStepClicked { get; set; }

    private static readonly List<string> StepNames = new()
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };

    private string GetStepCss(int index)
    {
        if (index < CurrentStep) return "completed";
        if (index == CurrentStep) return "active";
        return "future";
    }
}

@using sv_6329355a38764fa5b99dca67fe45b0e3.Models

<h3>Personal Information</h3>

<div class="mb-3">
    <label class="form-label">Full Name *</label>
    <input type="text" class="form-control" value="@FullName" @onchange="e => FullName = e.Value?.ToString() ?? string.Empty" />
</div>

<div class="mb-3">
    <label class="form-label">Email *</label>
    <input type="email" class="form-control" value="@Email" @onchange="e => Email = e.Value?.ToString() ?? string.Empty" />
    @if (!string.IsNullOrEmpty(emailError))
    {
        <div class="text-danger mt-1">@emailError</div>
    }
</div>

<div class="mb-3">
    <label class="form-label">Phone *</label>
    <input type="tel" class="form-control" value="@Phone" @onchange="e => Phone = e.Value?.ToString() ?? string.Empty" />
</div>

<div class="mb-3">
    <label class="form-label">Address *</label>
    <textarea class="form-control" rows="2" @onchange="e => Address = e.Value?.ToString() ?? string.Empty">@Address</textarea>
</div>

@if (!string.IsNullOrEmpty(validationError))
{
    <div class="alert alert-danger">@validationError</div>
}

<div class="d-flex justify-content-end">
    <button class="btn btn-primary" @onclick="HandleNext" disabled="@isValidating">
        @if (isValidating)
        {
            <span class="spinner-border spinner-border-sm me-1"></span>
        }
        Next
    </button>
</div>

@code {
    [Parameter] public PersonalInfo? Info { get; set; }
    [Parameter, EditorRequired] public EventCallback<PersonalInfo> OnNext { get; set; }
    [Parameter, EditorRequired] public IApplicationService ApplicationService { get; set; } = default!;

    private string FullName = string.Empty;
    private string Email = string.Empty;
    private string Phone = string.Empty;
    private string Address = string.Empty;
    private string? validationError;
    private string? emailError;
    private bool isValidating;

    protected override void OnParametersSet()
    {
        if (Info is not null)
        {
            FullName = Info.FullName;
            Email = Info.Email;
            Phone = Info.Phone;
            Address = Info.Address;
        }
    }

    private async Task HandleNext()
    {
        validationError = null;
        emailError = null;

        if (string.IsNullOrWhiteSpace(FullName) || string.IsNullOrWhiteSpace(Email)
            || string.IsNullOrWhiteSpace(Phone) || string.IsNullOrWhiteSpace(Address))
        {
            validationError = "All fields are required.";
            return;
        }

        isValidating = true;
        try
        {
            var emailValid = await ApplicationService.ValidateEmailAsync(Email);
            if (!emailValid)
            {
                emailError = "Please enter a valid email address.";
                return;
            }
        }
        finally
        {
            isValidating = false;
        }

        await OnNext.InvokeAsync(new PersonalInfo(FullName.Trim(), Email.Trim(), Phone.Trim(), Address.Trim()));
    }
}

@using sv_6329355a38764fa5b99dca67fe45b0e3.Models

<h3>Work History</h3>

@for (int i = 0; i < entries.Count; i++)
{
    var idx = i;
    var entry = entries[idx];
    <WorkEntryForm Index="idx"
                   CanRemove="entries.Count > 1"
                   Company="@entry.Company"
                   Title="@entry.Title"
                   StartDate="@entry.StartDate"
                   EndDate="@entry.EndDate"
                   IsCurrent="@entry.IsCurrent"
                   Description="@entry.Description"
                   OnChanged="data => UpdateEntry(idx, data)"
                   OnRemove="() => RemoveEntry(idx)" />
}

<button class="btn btn-outline-secondary mb-3" @onclick="AddEntry">
    + Add Another Position
</button>

@if (!string.IsNullOrEmpty(validationError))
{
    <div class="alert alert-danger">@validationError</div>
}

<div class="d-flex justify-content-between">
    <button class="btn btn-secondary" @onclick="OnBack">Back</button>
    <button class="btn btn-primary" @onclick="HandleNext">Next</button>
</div>

@code {
    [Parameter] public WorkHistory? History { get; set; }
    [Parameter, EditorRequired] public EventCallback<WorkHistory> OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private List<EntryModel> entries = new();
    private string? validationError;

    protected override void OnParametersSet()
    {
        if (entries.Count == 0)
        {
            if (History?.Entries is { Count: > 0 } existing)
            {
                entries = existing.Select(e => new EntryModel
                {
                    Company = e.Company,
                    Title = e.Title,
                    StartDate = e.StartDate,
                    EndDate = e.EndDate,
                    IsCurrent = e.EndDate == null,
                    Description = e.Description
                }).ToList();
            }
            else
            {
                entries.Add(new EntryModel());
            }
        }
    }

    private void AddEntry() => entries.Add(new EntryModel());

    private void RemoveEntry(int index)
    {
        if (entries.Count > 1)
            entries.RemoveAt(index);
    }

    private void UpdateEntry(int index, WorkEntryForm.WorkEntryData data)
    {
        if (index < entries.Count)
        {
            entries[index] = new EntryModel
            {
                Company = data.Company,
                Title = data.Title,
                StartDate = data.StartDate,
                EndDate = data.EndDate,
                IsCurrent = data.IsCurrent,
                Description = data.Description
            };
        }
    }

    private async Task HandleNext()
    {
        validationError = null;

        foreach (var entry in entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title) || entry.StartDate == null)
            {
                validationError = "Each position requires at least a company, title, and start date.";
                return;
            }
        }

        var workEntries = entries.Select(e => new WorkEntry(
            e.Company.Trim(),
            e.Title.Trim(),
            e.StartDate!.Value,
            e.IsCurrent ? null : e.EndDate,
            e.Description.Trim()
        )).ToList();

        await OnNext.InvokeAsync(new WorkHistory(workEntries));
    }

    private class EntryModel
    {
        public string Company { get; set; } = string.Empty;
        public string Title { get; set; } = string.Empty;
        public DateTime? StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = string.Empty;
    }
}

@using sv_6329355a38764fa5b99dca67fe45b0e3.Models

<h3>References</h3>
<p class="text-muted">Please provide 2-3 professional references.</p>

@for (int i = 0; i < references.Count; i++)
{
    var idx = i;
    var r = references[idx];
    <ReferenceForm Index="idx"
                   CanRemove="references.Count > 2"
                   Name="@r.Name"
                   Relationship="@r.Relationship"
                   Email="@r.Email"
                   Phone="@r.Phone"
                   OnChanged="data => UpdateReference(idx, data)"
                   OnRemove="() => RemoveReference(idx)" />
}

@if (references.Count < 3)
{
    <button class="btn btn-outline-secondary mb-3" @onclick="AddReference">
        + Add Reference
    </button>
}

@if (!string.IsNullOrEmpty(validationError))
{
    <div class="alert alert-danger">@validationError</div>
}

<div class="d-flex justify-content-between">
    <button class="btn btn-secondary" @onclick="OnBack">Back</button>
    <button class="btn btn-primary" @onclick="HandleNext">Next</button>
</div>

@code {
    [Parameter] public List<Reference>? References { get; set; }
    [Parameter, EditorRequired] public EventCallback<List<Reference>> OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private List<RefModel> references = new();
    private string? validationError;

    protected override void OnParametersSet()
    {
        if (references.Count == 0)
        {
            if (References is { Count: > 0 })
            {
                references = References.Select(r => new RefModel
                {
                    Name = r.Name, Relationship = r.Relationship, Email = r.Email, Phone = r.Phone
                }).ToList();
            }
            else
            {
                references.Add(new RefModel());
                references.Add(new RefModel());
            }
        }
    }

    private void AddReference()
    {
        if (references.Count < 3)
            references.Add(new RefModel());
    }

    private void RemoveReference(int index)
    {
        if (references.Count > 2)
            references.RemoveAt(index);
    }

    private void UpdateReference(int index, ReferenceForm.ReferenceData data)
    {
        if (index < references.Count)
        {
            references[index] = new RefModel
            {
                Name = data.Name, Relationship = data.Relationship, Email = data.Email, Phone = data.Phone
            };
        }
    }

    private async Task HandleNext()
    {
        validationError = null;

        foreach (var r in references)
        {
