@code {
    [Parameter] public WorkHistory? History { get; set; }
    [Parameter, EditorRequired] public EventCallback<WorkHistory> OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private List<EntryModel> entries = new();
    private string? validationError;

    protected override void OnParametersSet()
    {
        if (entries.Count == 0)
        {
            if (History?.Entries is { Count: > 0 } existing)
            {
                entries = existing.Select(e => new EntryModel
                {
                    Company = e.Company,
                    Title = e.Title,
                    StartDate = e.StartDate,
                    EndDate = e.EndDate,
                    IsCurrent = e.EndDate == null,
                    Description = e.Description
                }).ToList();
            }
            else
            {
                entries.Add(new EntryModel());
            }
        }
    }

    private void AddEntry() => entries.Add(new EntryModel());

    private void RemoveEntry(int index)
    {
        if (entries.Count > 1)
            entries.RemoveAt(index);
    }

    private void UpdateEntry(int index, WorkEntryForm.WorkEntryData data)
    {
        if (index < entries.Count)
        {
            entries[index] = new EntryModel
            {
                Company = data.Company,
                Title = data.Title,
                StartDate = data.StartDate,
                EndDate = data.EndDate,
                IsCurrent = data.IsCurrent,
                Description = data.Description
            };
        }
    }

    private async Task HandleNext()
    {
        validationError = null;

        foreach (var entry in entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title) || entry.StartDate == null)
            {
                validationError = "Each position requires at least a company, title, and start date.";
                return;
            }
        }

        var workEntries = entries.Select(e => new WorkEntry(
            e.Company.Trim(),
            e.Title.Trim(),
            e.StartDate!.Value,
            e.IsCurrent ? null : e.EndDate,
            e.Description.Trim()
        )).ToList();

        await OnNext.InvokeAsync(new WorkHistory(workEntries));
    }

    private class EntryModel
    {
        public string Company { get; set; } = string.Empty;
        public string Title { get; set; } = string.Empty;
        public DateTime? StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = string.Empty;
    }
}

