@using sv_6329355a38764fa5b99dca67fe45b0e3.Models

<h3>Personal Information</h3>

<div class="mb-3">
    <label class="form-label">Full Name *</label>
    <input type="text" class="form-control" value="@FullName" @onchange="e => FullName = e.Value?.ToString() ?? string.Empty" />
</div>

<div class="mb-3">
    <label class="form-label">Email *</label>
    <input type="email" class="form-control" value="@Email" @onchange="e => Email = e.Value?.ToString() ?? string.Empty" />
    @if (!string.IsNullOrEmpty(emailError))
    {
        <div class="text-danger mt-1">@emailError</div>
    }
</div>

<div class="mb-3">
    <label class="form-label">Phone *</label>
    <input type="tel" class="form-control" value="@Phone" @onchange="e => Phone = e.Value?.ToString() ?? string.Empty" />
</div>

<div class="mb-3">
    <label class="form-label">Address *</label>
    <textarea class="form-control" rows="2" @onchange="e => Address = e.Value?.ToString() ?? string.Empty">@Address</textarea>
</div>

@if (!string.IsNullOrEmpty(validationError))
{
    <div class="alert alert-danger">@validationError</div>
}

<div class="d-flex justify-content-end">
    <button class="btn btn-primary" @onclick="HandleNext" disabled="@isValidating">
        @if (isValidating)
        {
            <span class="spinner-border spinner-border-sm me-1"></span>
        }
        Next
    </button>
</div>

@code {
    [Parameter] public PersonalInfo? Info { get; set; }
    [Parameter, EditorRequired] public EventCallback<PersonalInfo> OnNext { get; set; }
    [Parameter, EditorRequired] public IApplicationService ApplicationService { get; set; } = default!;

    private string FullName = string.Empty;
    private string Email = string.Empty;
    private string Phone = string.Empty;
    private string Address = string.Empty;
    private string? validationError;
    private string? emailError;
    private bool isValidating;

    protected override void OnParametersSet()
    {
        if (Info is not null)
        {
            FullName = Info.FullName;
            Email = Info.Email;
            Phone = Info.Phone;
            Address = Info.Address;
        }
    }

    private async Task HandleNext()
    {
        validationError = null;
        emailError = null;

        if (string.IsNullOrWhiteSpace(FullName) || string.IsNullOrWhiteSpace(Email)
            || string.IsNullOrWhiteSpace(Phone) || string.IsNullOrWhiteSpace(Address))
        {
            validationError = "All fields are required.";
            return;
        }

        isValidating = true;
        try
        {
            var emailValid = await ApplicationService.ValidateEmailAsync(Email);
            if (!emailValid)
            {
                emailError = "Please enter a valid email address.";
                return;
            }
        }
        finally
        {
            isValidating = false;
        }

        await OnNext.InvokeAsync(new PersonalInfo(FullName.Trim(), Email.Trim(), Phone.Trim(), Address.Trim()));
    }
}

